from pathlib import Path
import json,hashlib,subprocess,datetime,html
root=Path('tools/review/world-reality-value-r1');h=lambda b:hashlib.sha256(b).hexdigest();e=html.escape
read=lambda p:json.loads((root/p).read_text(encoding='utf-8'))
questions=read('QUESTION-RESULTS.json')
judgments={1:('PARTIAL','能源与运输的真实正文可支持背景；尚未充分解释食品价格的传导强度。 / Energy and transport context is supported; food-price pass-through is incomplete.'),2:('PARTIAL','英文生活条件段落较直接；中文发展主义段落未充分解释工资分配，不能视为完整回答。 / The English living-conditions passage helps; the Chinese developmentalism passage does not establish wage distribution.'),3:('MISSING','没有通过准入的资源富裕与发展机制正文；不得用系统维护等不相关段落填充。 / No admitted passage establishes the resource-development mechanism.'),4:('PARTIAL','只有自动化/治理背景，尚未回答行业就业变化。 / Automation/governance context does not establish sector employment effects.'),5:('PARTIAL','两种语言均能读取人口、劳动、照护机制；缺本地规模与时间估计。 / Both languages retrieve population, labour and care mechanisms; local magnitude and timing remain unknown.'),6:('PARTIAL','工厂组织与投入协调有出处；水源、港口和电力的具体选址比较缺口保留。 / Factory coordination is sourced; water, port and power siting comparisons remain incomplete.'),7:('PARTIAL','历史战争与资源重组有出处，不能直接证明当前商品价格传导。 / Historical war and resource reconfiguration do not establish current commodity-price effects.'),8:('MISSING','没有马来西亚/越南同口径产业数据；通用工厂段落不能算比较答案。 / Generic factory passages cannot substitute for aligned Malaysia/Vietnam data.'),9:('PARTIAL','产品保留原有利率成本机制；没有个人审批概率或完整银行授信判断。 / The product retains the rate-cost mechanism; it does not establish personal approval probability.'),10:('PARTIAL','已有工作、收入、生活成本的背景解释；具体职业选择由用户在 Reality 明确比较和选择。 / Work, income and cost context is sourced; personal choices remain user-owned.')}
rows=[]
for i in range(1,11):
 pair=[q for q in questions if q['id']==i];status,note=judgments[i]
 details=''.join('<details><summary>'+e(q['locale'])+' · '+e(q['question'])+'</summary><p>'+e(q['product']['directAnswer'])+'</p>'+''.join('<p><a href="'+e('https://getphios.com'+s['href'] if s['href'].startswith('/') else s['href'])+'">'+e(s['title'])+'</a></p><blockquote>'+e(s['text'])+'</blockquote>' for s in q['explanation']['sources'])+'</details>' for q in pair)
 rows.append(f'<article><h3>{i}. {status}</h3><p>{e(note)}</p>{details}</article>')
shots=[{'path':p.name,'bytes':p.stat().st_size,'sha256':h(p.read_bytes()),'kind':'representative_final_synthetic_only'} for p in root.glob('final-*.png')]
